links=[('새 실행 파일','EngineMigrator-runtime-enable-preview-20261023/EngineMigrator.App.exe'),('배포 ZIP','EngineMigrator-runtime-enable-preview-20261023.zip'),('HTML 가이드','../docs/guide.html'),('전체 검증 근거','runtime-enable-tests/milestone-verification.json'),('실제 왕복 데이터','runtime-enable-roundtrip/PROJECT-b2596a4ebc0f/project-roundtrip-verification.json'),('복원 프로젝트 대응표','runtime-enable-roundtrip/PROJECT-b2596a4ebc0f/resource-port.html'),('이전 컴포넌트 검증','development-report-runtime-component-20261023.html')]
